// Generate the JS + Rust mirrors of the unified error-code registry from the single source
// `error-codes.json` (see plan/design.error-model.md). Run after editing the source:
//     node scripts/gen-error-codes.mjs
// CI runs it in check mode (fails if a generated file is stale — the drift gate):
//     node scripts/gen-error-codes.mjs --check
//
// Emits:
//   apps/app/src/core/errorCodes.generated.js  — the code metadata map + string consts (client + UI)
//   openom/src/error_codes.rs                   — code &str consts, a metadata table, and typed arg structs (server)
// The wasm-core (third mirror, B3) reuses openom's crate consts once the app-core error path lands.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SRC = path.join(REPO, 'error-codes.json');
const JS_OUT = path.join(REPO, 'apps', 'app', 'src', 'core', 'errorCodes.generated.js');
// Two Rust mirrors (separate crates can't share a module): the managed server, and the wasm-core (which will
// emit AppErrors from the Rust side once the 9457 parse moves in-core — B3). Identical generated content.
const RS_OUTS = [
  path.join(REPO, 'openom', 'src', 'error_codes.rs'),
  path.join(REPO, 'packages', 'openom-app-core', 'src', 'error_codes.rs'),
];

const ARG_TYPES = { u64: 'u64', u32: 'u32', string: 'String' }; // allowed arg value types (Rust mapping)
const GUARD = '// @generated by scripts/gen-error-codes.mjs from error-codes.json — DO NOT EDIT.';

function fail(msg) {
  console.error(`error-codes: ${msg}`);
  process.exit(1);
}

function validate(reg) {
  const domains = new Set(reg.domains);
  const actions = new Set(reg.actions);
  for (const [code, m] of Object.entries(reg.codes)) {
    if (!/^[a-z][a-z0-9_]*$/.test(code)) fail(`code "${code}" must be snake_case`);
    if (!domains.has(m.domain)) fail(`code "${code}" has unknown domain "${m.domain}"`);
    if (typeof m.title !== 'string' || !m.title.trim()) fail(`code "${code}" needs a non-empty title`);
    if (typeof m.retriable !== 'boolean') fail(`code "${code}" needs a boolean retriable`);
    if (m.action !== null && !actions.has(m.action)) fail(`code "${code}" has unknown action "${m.action}"`);
    // Coherence (E4): retriable ⇒ action is retry|null; permanent ⇒ action is not retry.
    if (m.retriable && !(m.action === 'retry' || m.action === null)) {
      fail(`code "${code}" is retriable but action "${m.action}" is not retry/null (E4 coherence)`);
    }
    if (!m.retriable && m.action === 'retry') {
      fail(`code "${code}" is permanent but action is 'retry' (E4 coherence)`);
    }
    for (const a of m.args ?? []) {
      if (!/^[a-z][a-zA-Z0-9]*$/.test(a.name)) fail(`code "${code}" arg "${a.name}" must be lowerCamel/snake`);
      if (!ARG_TYPES[a.type]) fail(`code "${code}" arg "${a.name}" has non-allowed type "${a.type}" (counts/limits/seconds/enums only)`);
    }
  }
}

function pascal(code) {
  return code.replace(/(^|_)([a-z0-9])/g, (_, __, c) => c.toUpperCase());
}

const jsStr = (s) => s.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
const rsStr = (s) => s.replace(/\\/g, '\\\\').replace(/"/g, '\\"');

function genJs(reg) {
  const lines = [GUARD, '', '/** The closed error-code registry (domain/retriable/action/args) — the client + UI mirror. */'];
  lines.push('export const ERROR_CODES = Object.freeze({');
  for (const [code, m] of Object.entries(reg.codes)) {
    const args = (m.args ?? []).map((a) => `{ name: '${a.name}', type: '${a.type}' }`).join(', ');
    const action = m.action === null ? 'null' : `'${m.action}'`;
    lines.push(`  ${code}: Object.freeze({ domain: '${m.domain}', title: '${jsStr(m.title)}', retriable: ${m.retriable}, action: ${action}, args: Object.freeze([${args}]) }),`);
  }
  lines.push('});', '');
  lines.push('/** Every valid code string, for guard checks. */');
  lines.push(`export const CODES = Object.freeze(Object.keys(ERROR_CODES));`, '');
  lines.push('/** The Fluent key for a code: `error-${domain}-${code}`, kebab-cased (Fluent ids allow neither');
  lines.push(' *  dots nor a clean hierarchy), with a redundant leading `${domain}_` stripped from the code so');
  lines.push(' *  storage_quota (storage) -> `error-storage-quota`, below_gc_floor (sync) -> `error-sync-below-gc-floor`. */');
  lines.push('export function fluentKey(code) {');
  lines.push('  const m = ERROR_CODES[code];');
  lines.push('  if (!m) return \'error-generic\';');
  lines.push("  const tail = code.startsWith(`${m.domain}_`) ? code.slice(m.domain.length + 1) : code;");
  lines.push("  return `error-${m.domain}-${tail.replaceAll('_', '-')}`;");
  lines.push('}', '');
  return lines.join('\n');
}

function genRust(reg) {
  const lines = [GUARD, '#![allow(dead_code)]', '', '//! The closed error-code registry (server mirror). See `plan/design.error-model.md`.', ''];
  lines.push('/// One row of code metadata.');
  lines.push('pub struct CodeMeta {');
  lines.push('    pub code: &\'static str,');
  lines.push('    pub domain: &\'static str,');
  lines.push('    pub title: &\'static str,');
  lines.push('    pub retriable: bool,');
  lines.push('    pub action: Option<&\'static str>,');
  lines.push('}', '');
  // Per-code &str consts for ergonomic, typo-proof use at emission sites.
  for (const code of Object.keys(reg.codes)) {
    lines.push(`pub const ${code.toUpperCase()}: &str = "${code}";`);
  }
  lines.push('');
  lines.push('/// Every code + its metadata, in source order.');
  lines.push('pub const ERROR_CODES: &[CodeMeta] = &[');
  for (const [code, m] of Object.entries(reg.codes)) {
    const action = m.action === null ? 'None' : `Some("${m.action}")`;
    lines.push(`    CodeMeta { code: "${code}", domain: "${m.domain}", title: "${rsStr(m.title)}", retriable: ${m.retriable}, action: ${action} },`);
  }
  lines.push('];', '');
  lines.push('/// The stable RFC 9457 `title` for a code (falls back to a generic label for an unknown code).');
  lines.push('#[must_use]');
  lines.push('pub fn title_for(code: &str) -> &\'static str {');
  lines.push('    ERROR_CODES.iter().find(|m| m.code == code).map_or("Error", |m| m.title)');
  lines.push('}', '');
  // Typed arg structs (A4) for codes that carry args.
  for (const [code, m] of Object.entries(reg.codes)) {
    if (!(m.args ?? []).length) continue;
    lines.push(`/// Interpolation args for \`${code}\`.`);
    lines.push(`pub struct ${pascal(code)}Args {`);
    for (const a of m.args) lines.push(`    pub ${a.name}: ${ARG_TYPES[a.type]},`);
    lines.push('}', '');
  }
  return lines.join('\n');
}

function writeOrCheck(file, content, check) {
  const rel = path.relative(REPO, file);
  if (check) {
    const cur = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
    if (cur !== content) fail(`${rel} is stale — run \`node scripts/gen-error-codes.mjs\` and commit`);
    return;
  }
  fs.writeFileSync(file, content);
  console.log(`wrote ${rel}`);
}

const check = process.argv.includes('--check');
const reg = JSON.parse(fs.readFileSync(SRC, 'utf8'));
validate(reg);
writeOrCheck(JS_OUT, `${genJs(reg)}\n`, check);
const rust = `${genRust(reg)}\n`;
for (const out of RS_OUTS) writeOrCheck(out, rust, check);
if (check) console.log('error-codes: generated files are up to date');
